WITH x AS (
  SELECT u.*, COUNT(*) OVER (PARTITION BY email) AS copies
  FROM users u
)
SELECT * FROM x WHERE copies > 1;

WITH ranked AS (
  SELECT id, ROW_NUMBER() OVER (
    PARTITION BY email ORDER BY updated_at DESC, id DESC
  ) AS rn
  FROM users
)
SELECT id FROM ranked WHERE rn > 1;

WITH ranked AS (
  SELECT o.*, ROW_NUMBER() OVER (
    PARTITION BY customer_id ORDER BY created_at DESC, id DESC
  ) AS rn
  FROM orders o
)
SELECT * FROM ranked WHERE rn = 1;

WITH r AS (
  SELECT salary, DENSE_RANK() OVER (ORDER BY salary DESC) AS pos
  FROM employees
)
SELECT DISTINCT salary FROM r WHERE pos = 2;

WITH r AS (
  SELECT salary, DENSE_RANK() OVER (ORDER BY salary DESC) AS pos
  FROM employees
)
SELECT DISTINCT salary FROM r WHERE pos = :n;

WITH r AS (
  SELECT p.*, ROW_NUMBER() OVER (
    PARTITION BY category_id ORDER BY revenue DESC, id
  ) AS rn
  FROM products p
)
SELECT * FROM r WHERE rn <= 3;

SELECT c.*
FROM customers c
WHERE NOT EXISTS (
  SELECT 1 FROM orders o WHERE o.customer_id = c.id
);

SELECT o.*
FROM orders o
WHERE o.customer_id IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM customers c WHERE c.id = o.customer_id
  );

SELECT id, status, amount FROM expected
EXCEPT
SELECT id, status, amount FROM actual;

WITH x AS (
  SELECT e.*, LAG(status) OVER (
    PARTITION BY entity_id ORDER BY occurred_at, id
  ) AS previous_status
  FROM events e
)
SELECT * FROM x
WHERE previous_status IS NOT NULL
  AND status <> previous_status;
